// Hubla (v2) -> public.hubla_carrinho_abandonado. Contrato: docs/contrato-dados.md.
// Evento: lead.abandoned_checkout. Chave: lead_id, lead_created_at (sem data, usa a hora do recebimento).
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const get = (o, p) => p.split('.').reduce((a, k) => (a && typeof a === 'object') ? a[k] : undefined, o);
const first = (...ps) => { for (const p of ps) { const v = get(body, p); if (v !== undefined && v !== null && !(typeof v === 'string' && v.trim() === '')) return v; } return null; };
const txt = (v) => (v === null || typeof v === 'object') ? null : (String(v).trim() || null);
const ts = (v) => { const s = txt(v); if (!s) return null; const dt = DateTime.fromISO(s.replace(' ', 'T'), { zone: 'UTC-3' }); return dt.isValid ? dt.toISO() : null; };

const leadId = txt(first('event.lead.id', 'event.user.id', 'event.leadId'));
if (!leadId) throw new Error('Hubla Carrinho: lead_id ausente (type ' + (txt(body.type) ?? 'ausente') + '). Confira os eventos marcados na regra da Hubla.');
const nome = txt(first('event.lead.fullName', 'event.lead.name', 'event.user.name')) ?? txt([first('event.lead.firstName', 'event.user.firstName'), first('event.lead.lastName', 'event.user.lastName')].filter(Boolean).join(' '));
const utm = (k) => txt(first('event.lead.session.utm.' + k, 'event.session.utm.' + k, 'event.lead.utm.' + k, 'event.utm.' + k, 'event.paymentSession.utm.' + k));

return { json: {
  lead_id: leadId,
  lead_created_at: ts(first('event.lead.createdAt', 'event.createdAt')) ?? DateTime.now().toISO(),
  event_type: txt(body.type),
  nome,
  email: txt(first('event.lead.email', 'event.user.email')),
  telefone: txt(first('event.lead.phone', 'event.user.phone')),
  product_id: txt(first('event.product.id', 'event.products.0.id', 'event.lead.product.id')),
  product_name: txt(first('event.product.name', 'event.products.0.name', 'event.lead.product.name')),
  offer_id: txt(first('event.products.0.offers.0.id', 'event.offer.id', 'event.lead.offer.id')),
  offer_name: txt(first('event.products.0.offers.0.name', 'event.offer.name', 'event.lead.offer.name')),
  checkout_url: txt(first('event.lead.session.url', 'event.lead.checkoutUrl', 'event.checkoutUrl', 'event.session.url')),
  utm_source: utm('source'), utm_medium: utm('medium'), utm_campaign: utm('campaign'), utm_content: utm('content'), utm_term: utm('term'),
  raw_payload: body
} };
